heavy_keepers_add.impl:
let idx = (aux & 0xF) * 4;
let count = (val >> idx) & 0xF;
let is_not_max = (count < 15) as u64;
let new_count = count + is_not_max;
(val & !(0xF << idx)) | (new_count << idx)

heavy_keepers_add.ref:
