weighted_reservoir_sample.impl:
let w1 = val; let w2 = aux;
let mask = 0u64.wrapping_sub((w1 > w2) as u64);
(w1 & mask) | (w2 & !mask)

hashing_trick_u64.impl:
let mut x = val;
x = x.wrapping_mul(0xbf58476d1ce4e5b9);
x = (x ^ (x >> 30)).wrapping_mul(0x94d049bb133111eb);
x = (x ^ (x >> 27)).wrapping_mul(0xff51afd7ed558ccd);
x = x ^ (x >> 33);
x % (aux | 1)

