locality_sensitive_hash_euclidean.impl:
let mut dist_sq = 0u64;
for i in 0..8 {
    let a = ((val >> (i * 8)) & 0xFF) as i64; let b = ((aux >> (i * 8)) & 0xFF) as i64;
    dist_sq += ((a - b) * (a - b)) as u64;
}
dist_sq / 100

locality_sensitive_hash_euclidean.ref:
let mut dist_sq = 0u64;
for i in 0..8 {
    let a = ((val >> (i * 8)) & 0xFF) as i64; let b = ((aux >> (i * 8)) & 0xFF) as i64;
    let diff = if a > b { a - b } else { b - a };
    dist_sq += (diff * diff) as u64;
}
dist_sq / 100
